(() => {
  'use strict';
  const canvas = document.querySelector('#game');
  const ctx = canvas.getContext('2d');
  const W = 1280, H = 720, floorY = 610;
  const pieces = [
    { name: 'LONG PLANK', kind: 'wood', w: 138, h: 24, color: '#c98249', hp: 2, count: 5, cost: 1 },
    { name: 'STONE', kind: 'stone', w: 72, h: 52, color: '#858da3', hp: 4, count: 4, cost: 2 },
    { name: 'GLASS', kind: 'glass', w: 98, h: 16, color: '#82d8e6', hp: 1, count: 3, cost: 1 },
    { name: 'SHORT PLANK', kind: 'wood', w: 72, h: 22, color: '#d59658', hp: 2, count: 4, cost: 1 }
  ];
  let state = 'intro', selected = -1, blocks = [], birds = [], particles = [], drag = null;
  let score = 0, shots = 4, shotTimer = 0, quietTimer = 0, bestScore = 0, buildLeft = 0, toast = '', toastTime = 0;
  const sling = { x: 300, y: 536 }, world = { left: 178, right: 1084, top: 144, floor: floorY };
  const clamp = (n, a, b) => Math.max(a, Math.min(b, n));
  const rand = (a, b) => a + Math.random() * (b - a);
  function reset() {
    pieces.forEach(p => p.count = p.name === 'LONG PLANK' ? 5 : p.name === 'STONE' ? 4 : p.name === 'GLASS' ? 3 : 4);
    blocks = []; birds = []; particles = []; selected = -1; score = 0; shots = 4; buildLeft = 0;
    state = 'build'; toast = 'Build a tower on the platform. Make it sturdy!'; toastTime = 3.2;
  }
  function rounded(x, y, w, h, r, fill, stroke, line = 1) {
    ctx.beginPath(); ctx.roundRect(x, y, w, h, r); if (fill) { ctx.fillStyle = fill; ctx.fill(); }
    if (stroke) { ctx.lineWidth = line; ctx.strokeStyle = stroke; ctx.stroke(); }
  }
  function text(str, x, y, size, color = '#f7f5eb', align = 'left', weight = 700) {
    ctx.font = `${weight} ${size}px Inter, system-ui, sans-serif`; ctx.textAlign = align; ctx.textBaseline = 'middle'; ctx.fillStyle = color; ctx.fillText(str, x, y);
  }
  function button(label, x, y, w, h, fill, action, sub = '') {
    rounded(x, y + 4, w, h, 14, 'rgba(0,0,0,.2)'); rounded(x, y, w, h, 14, fill, 'rgba(255,255,255,.25)', 1.5);
    text(label, x + w / 2, y + h / 2 - (sub ? 7 : 0), 16, '#fff', 'center', 900);
    if (sub) text(sub, x + w / 2, y + h / 2 + 13, 10, 'rgba(255,255,255,.78)', 'center', 700);
    return { x, y, w, h, action };
  }
  function roundedRectPath(x, y, w, h, r) { ctx.beginPath(); ctx.roundRect(x, y, w, h, r); }
  function drawBackground() {
    const sky = ctx.createLinearGradient(0, 0, 0, H); sky.addColorStop(0, '#78c9e8'); sky.addColorStop(.63, '#c7e9e9'); sky.addColorStop(1, '#e5ddb0'); ctx.fillStyle = sky; ctx.fillRect(0, 0, W, H);
    // sun, clouds and rolling hills
    ctx.fillStyle = 'rgba(255,244,179,.72)'; ctx.beginPath(); ctx.arc(1070, 140, 55, 0, Math.PI * 2); ctx.fill();
    for (const [x, y, s] of [[210,145,1],[560,105,.72],[890,230,.65]]) {
      ctx.fillStyle = 'rgba(255,255,255,.52)'; ctx.beginPath(); ctx.ellipse(x,y,45*s,16*s,0,0,Math.PI*2); ctx.ellipse(x+25*s,y-9*s,28*s,19*s,0,0,Math.PI*2); ctx.ellipse(x-22*s,y-6*s,24*s,15*s,0,0,Math.PI*2); ctx.fill();
    }
    ctx.fillStyle = '#9bceaa'; ctx.beginPath(); ctx.moveTo(0,434); ctx.quadraticCurveTo(226,320,465,430); ctx.quadraticCurveTo(730,540,1000,398); ctx.quadraticCurveTo(1160,337,1280,405); ctx.lineTo(1280,640); ctx.lineTo(0,640); ctx.fill();
    ctx.fillStyle = '#75b88b'; ctx.beginPath(); ctx.moveTo(0,508); ctx.quadraticCurveTo(250,418,494,505); ctx.quadraticCurveTo(829,596,1050,470); ctx.quadraticCurveTo(1170,421,1280,480); ctx.lineTo(1280,640); ctx.lineTo(0,640); ctx.fill();
    // distant tiny trees
    for (let x = 35; x < 1280; x += 94) { const y = 520 + Math.sin(x * .03) * 28; ctx.fillStyle = '#4d9877'; ctx.fillRect(x, y, 7, 45); ctx.beginPath(); ctx.arc(x+4,y,18,0,Math.PI*2); ctx.fill(); }
    // ground
    ctx.fillStyle = '#e8c879'; ctx.fillRect(0, floorY, W, H-floorY); ctx.fillStyle = '#fff0b0'; ctx.fillRect(0, floorY, W, 8);
    for (let i=0;i<60;i++) { const x=(i*173)%W, y=floorY+18+(i*47)%92; ctx.fillStyle = i%2 ? 'rgba(153,108,52,.12)' : 'rgba(255,255,255,.17)'; ctx.beginPath(); ctx.ellipse(x,y,randSeed(i,8,18),2,0,0,Math.PI*2); ctx.fill(); }
    // build pad
    rounded(671, floorY-12, 367, 20, 8, '#b57c53', '#f4d293', 2); ctx.fillStyle = 'rgba(255,255,255,.15)'; ctx.fillRect(686,floorY-7,335,3);
  }
  function randSeed(i,a,b) { return a + ((i*37)%100)/100*(b-a); }
  function drawSling() {
    // forked slingshot
    ctx.lineCap = 'round'; ctx.lineWidth = 17; ctx.strokeStyle = '#77452f'; ctx.beginPath(); ctx.moveTo(sling.x, floorY-4); ctx.lineTo(sling.x+2, sling.y-13); ctx.lineTo(sling.x-20,sling.y-58); ctx.moveTo(sling.x+2,sling.y-13); ctx.lineTo(sling.x+24,sling.y-57); ctx.stroke();
    ctx.lineWidth = 7; ctx.strokeStyle = '#a86b40'; ctx.beginPath(); ctx.moveTo(sling.x,floorY-4); ctx.lineTo(sling.x+2,sling.y-13); ctx.stroke();
    if (state === 'aim' && drag) {
      ctx.strokeStyle = '#704334'; ctx.lineWidth = 4; ctx.beginPath(); ctx.moveTo(sling.x-20,sling.y-58); ctx.lineTo(drag.x,drag.y); ctx.lineTo(sling.x+24,sling.y-57); ctx.stroke();
      ctx.setLineDash([6,7]); ctx.strokeStyle = 'rgba(255,255,255,.72)'; ctx.lineWidth = 2; ctx.beginPath();
      const vx=(sling.x-drag.x)*.14, vy=(sling.y-drag.y)*.14; for(let i=0;i<24;i++){let t=i*.13; const px=sling.x+vx*t, py=sling.y+vy*t+0.5*420*t*t; if(i===0)ctx.moveTo(px,py);else ctx.lineTo(px,py);} ctx.stroke(); ctx.setLineDash([]);
    }
    const bx=state==='aim'&&drag?drag.x:sling.x; const by=state==='aim'&&drag?drag.y:sling.y;
    if(state==='build'||state==='aim') drawBird(bx,by,20);
  }
  function drawBird(x,y,r) {
    ctx.save(); ctx.shadowColor='rgba(33,35,42,.22)';ctx.shadowBlur=8;ctx.shadowOffsetY=4;
    ctx.fillStyle='#ed5547';ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);ctx.fill();ctx.shadowColor='transparent';
    ctx.fillStyle='#fff4dc';ctx.beginPath();ctx.ellipse(x+6,y+5,9,7,-.3,0,Math.PI*2);ctx.fill();
    ctx.fillStyle='#fff';ctx.beginPath();ctx.arc(x+6,y-5,6,0,Math.PI*2);ctx.arc(x+14,y-4,5,0,Math.PI*2);ctx.fill();
    ctx.fillStyle='#263448';ctx.beginPath();ctx.arc(x+8,y-5,2.1,0,Math.PI*2);ctx.arc(x+15,y-4,1.8,0,Math.PI*2);ctx.fill();
    ctx.fillStyle='#f6b83f';ctx.beginPath();ctx.moveTo(x+10,y+1);ctx.lineTo(x+26,y+5);ctx.lineTo(x+10,y+9);ctx.closePath();ctx.fill();
    ctx.restore();
  }

function drawBlock(b) {
  ctx.save(); ctx.translate(b.x,b.y); ctx.rotate(b.a||0);
  const w=b.w,h=b.h;
  ctx.shadowColor='rgba(28,48,53,.2)';ctx.shadowBlur=7;ctx.shadowOffsetY=4;
  if(b.kind==='glass') { ctx.fillStyle='rgba(112,224,237,.72)';ctx.strokeStyle='#e7ffff'; }
  else if(b.kind==='stone') { ctx.fillStyle='#858da3';ctx.strokeStyle='#b9c1d0'; }
  else { ctx.fillStyle=b.color||'#c98249';ctx.strokeStyle='#f0bd7d'; }
  ctx.lineWidth=3; roundedRectPath(-w/2,-h/2,w,h,Math.min(7,h/4));ctx.fill();ctx.stroke();ctx.shadowColor='transparent';
  if(b.kind==='wood') { ctx.strokeStyle='rgba(97,48,26,.36)';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(-w*.35,0);ctx.lineTo(w*.35,0);ctx.stroke(); }
  if(b.kind==='stone') { ctx.fillStyle='rgba(255,255,255,.16)';ctx.beginPath();ctx.arc(-w*.24,-h*.2,4,0,Math.PI*2);ctx.arc(w*.2,h*.2,3,0,Math.PI*2);ctx.fill(); }
  if(b.kind==='glass') { ctx.fillStyle='rgba(255,255,255,.68)';ctx.fillRect(-w*.38,-h*.27,w*.24,3); }
  if(b.hp < b.maxHp) { ctx.strokeStyle='rgba(50,38,38,.65)';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(-w*.13,-h*.4);ctx.lineTo(-w*.02,0);ctx.lineTo(-w*.2,h*.35);ctx.stroke(); }
  ctx.restore();
}
function drawPig(p) {
  ctx.save();ctx.translate(p.x,p.y);ctx.fillStyle=p.hp>0?'#84c958':'#63844b';
  ctx.beginPath();ctx.ellipse(0,0,22,19,0,0,Math.PI*2);ctx.fill();
  ctx.fillStyle='#a7df75';ctx.beginPath();ctx.ellipse(-10,-16,7,10,-.5,0,Math.PI*2);ctx.ellipse(10,-16,7,10,.5,0,Math.PI*2);ctx.fill();
  ctx.fillStyle='#fff';ctx.beginPath();ctx.arc(-7,-3,5,0,Math.PI*2);ctx.arc(7,-3,5,0,Math.PI*2);ctx.fill();ctx.fillStyle='#263448';ctx.beginPath();ctx.arc(-6,-2,2,0,Math.PI*2);ctx.arc(8,-2,2,0,Math.PI*2);ctx.fill();
  ctx.fillStyle='#64a743';ctx.beginPath();ctx.ellipse(0,6,8,5,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#3c783f';ctx.beginPath();ctx.arc(-3,6,1.3,0,Math.PI*2);ctx.arc(3,6,1.3,0,Math.PI*2);ctx.fill();
  if (p.hp<=0){ctx.strokeStyle='#e8f4dc';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(-8,-5);ctx.lineTo(-3,0);ctx.moveTo(-3,-5);ctx.lineTo(-8,0);ctx.moveTo(4,-5);ctx.lineTo(9,0);ctx.moveTo(9,-5);ctx.lineTo(4,0);ctx.stroke();}
  ctx.restore();
}
function drawHUD() {
  rounded(24,22,380,70,19,'rgba(16,30,50,.84)','rgba(255,255,255,.22)');
  text('BIRDS',45,47,19,'#ffcb62');text('& BRICKS',111,47,19,'#fff');text('BUILD. BRACE. BONK.',46,72,11,'#bad0d4', 'left',800);
  rounded(1015,24,240,64,17,'rgba(16,30,50,.78)','rgba(255,255,255,.2)');
  text('SCORE',1038,45,11,'#b4c9d1');text(String(score).padStart(5,'0'),1038,68,22,'#fff', 'left',900);
  text('♥  '+(state==='build'?'4':Math.max(0,Math.ceil((buildLeft||shots)))),1178,48,14,'#ffd56d','center',900);
  if(state==='build'||state==='aim') {
    rounded(414,24,482,58,16,'rgba(255,255,255,.76)','rgba(255,255,255,.6)');
    text(state==='build'?'YOUR TURN  ·  FORTIFY THE NEST':'READY, AIM…',655,44,13,'#264b5b','center',900);
    text(state==='build'?'Stack blocks around your pig, then launch the attack.':'Drag back and release to fling your bird!',655,64,11,'#55727a','center',700);
  } else if(state==='attack') {
    rounded(435,24,410,58,16,'rgba(30,40,58,.75)','rgba(255,255,255,.2)');text('INCOMING! FRIEND IS ATTACKING',640,43,13,'#fff','center',900);text('Hold your tower together!',640,64,11,'#cfdae0','center',700);
  }
}
let uiButtons=[];
function drawTray() {
  uiButtons=[];
  if(state==='build'||state==='aim') {
    rounded(18,626,1244,80,17,'rgba(19,35,49,.92)','rgba(255,255,255,.2)',1.5);
    text('BUILD KIT',38,646,10,'#9fbac1','left',900);
    pieces.forEach((p,i)=>{
      const x=34+i*147, y=655, active=selected===i;
      rounded(x,y,137,42,10,active?'#e7b45a':'#304c5d',active?'#fff0b0':'rgba(255,255,255,.14)',active?2:1);
      ctx.fillStyle=p.color;ctx.fillRect(x+10,y+13,26,15);ctx.strokeStyle='rgba(255,255,255,.6)';ctx.strokeRect(x+10,y+13,26,15);
      text(p.name,x+43,y+13,9,active?'#382f20':'#fff','left',900);text('× '+p.count,x+43,y+30,10,active?'#57462b':'#b9d1d2','left',700);
    });
    uiButtons.push(button('ROTATE  R',635,652,111,40,'#476478',()=>rotateSelected(),'Turn block'));
    if(state==='build') uiButtons.push(button('LET HIM TRY  →',765,646,211,50,'#df7350',startAttack,'Start the attack'));
    else uiButtons.push(button('CANCEL',765,646,211,50,'#566778',cancelAim,'Back to build'));
    uiButtons.push(button('RESET',1101,652,117,40,'#405367',reset));
  } else if(state==='end') {
    rounded(18,626,1244,80,17,'rgba(19,35,49,.92)','rgba(255,255,255,.2)',1.5);
    text('THE ROUND IS OVER',40,655,14,'#f5d875','left',900);text('Want a rematch? Build a better nest.',40,680,11,'#b9d1d2','left',700);
    uiButtons.push(button('PLAY AGAIN',1034,644,190,52,'#df7350',reset));
  } else if(state==='intro') {
    rounded(18,626,1244,80,17,'rgba(19,35,49,.92)','rgba(255,255,255,.2)',1.5);
    text('HOW TO PLAY',40,650,11,'#ffd36c','left',900);text('Pick blocks · click to place · drag to aim · let your friend attack!',40,678,15,'#fff','left',700);
    uiButtons.push(button('PLAY',1050,644,174,52,'#df7350',reset));
  }
}
function drawOverlay() {
  if(state==='intro') {
    ctx.fillStyle='rgba(13,27,42,.23)';ctx.fillRect(0,0,W,H);
    rounded(355,172,570,333,28,'rgba(20,39,55,.91)','rgba(255,255,255,.3)',2);
    text('BIRDS',640,229,48,'#ffd065','center',1000);text('& BRICKS',640,277,48,'#fff','center',1000);
    text('BUILD A TOWER. YOUR FRIEND TRIES TO BREAK IT.',640,332,14,'#a8cbd1','center',900);
    // playful little icon story
    drawBird(510,400,23); text('VS',640,405,15,'#f4d480','center',900);drawPig({x:770,y:400,hp:1});
    text('Stack smart. See how many hits your nest can take.',640,457,13,'#e1ebdf','center',700);
    text('A tiny physics playground for friendly rivalries.',640,481,11,'#99b6bb','center',600);
  }
  if(state==='end') {
    ctx.fillStyle='rgba(14,26,42,.28)';ctx.fillRect(0,0,W,H);
    rounded(390,205,500,272,25,'rgba(21,39,54,.94)','rgba(255,255,255,.26)',2);
    const won=blocks.length>0&&blocks.some(b=>b.hp>0)&& (score>=250||shots<=0);
    text(won?'NEST DEFENDED!':'TOWER DOWN!',640,267,30,won?'#f7d16b':'#ff9679','center',1000);
    text(won?'Your friend ran out of ammo. Nice building!':'Your friend got through. Build it sturdier!',640,314,14,'#ecf1e8','center',700);
    text(`FINAL SCORE   ${String(score).padStart(5,'0')}`,640,365,16,'#fff','center',900);
    text('Your best: '+String(bestScore).padStart(5,'0'),640,396,12,'#b4c9ce','center',700);
  }
  if(toastTime>0 && state!=='intro'&&state!=='end') {
    rounded(400,105,480,34,11,'rgba(17,35,50,.65)');text(toast,640,122,12,'#fff','center',800);
  }
}
function draw() {
  ctx.clearRect(0,0,W,H);drawBackground();
  // target nook and home sign
  rounded(888,547,145,54,10,'#d7b27c','#f6d69d',2);text('THE NEST',960,578,10,'#795a3a','center',900);
  // the friend/pig protected by the tower
  const pig={x:960,y:floorY-22,hp:1};drawPig(pig);
  blocks.forEach(drawBlock);
  birds.forEach(b=>drawBird(b.x,b.y,b.r||18));
  particles.forEach(p=>{ctx.globalAlpha=clamp(p.life,0,1);ctx.fillStyle=p.color;ctx.beginPath();ctx.arc(p.x,p.y,p.r,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;});
  drawSling();drawHUD();drawTray();drawOverlay();
  if(state==='build'&&selected>=0&&drag) { const p=pieces[selected]; ctx.globalAlpha=.65;drawBlock({x:drag.x,y:drag.y,w:p.w,h:p.h,kind:p.kind,color:p.color,hp:p.hp,maxHp:p.hp,a:0});ctx.globalAlpha=1; }
}

  function collides(a,b) { return Math.abs(a.x-b.x)<(a.w+b.w)*.48 && Math.abs(a.y-b.y)<(a.h+b.h)*.48; }
  function placeBlock(x,y) {
    if(selected<0||pieces[selected].count<=0)return;
    const p=pieces[selected], b={x,y,w:p.w,h:p.h,kind:p.kind,color:p.color,hp:p.hp,maxHp:p.hp,a:0,vx:0,vy:0,weight:p.kind==='stone'?2:1,placed:true};
    // settle on the floor, platform or existing blocks
    b.y=clamp(b.y,world.top, floorY-b.h/2-2);
    for(let i=0;i<5;i++) for(const other of blocks) {
      if(Math.abs(b.x-other.x)<(b.w+other.w)/2-5 && Math.abs(b.y-other.y)<(b.h+other.h)/2) {
        const above=other.y-(other.h+b.h)/2-1, below=other.y+(other.h+b.h)/2+1;
        b.y=Math.abs(b.y-above)<Math.abs(b.y-below)?above:below;
      }
    }
    b.x=clamp(b.x,world.left+b.w/2,world.right-b.w/2);
    if(blocks.some(q=>Math.abs(b.x-q.x)<(b.w+q.w)/2-7&&Math.abs(b.y-q.y)<(b.h+q.h)/2-7)) { toast='That spot is already occupied.';toastTime=1.4;return; }
    blocks.push(b);p.count--;selected=-1;drag=null;
  }
  function startAttack() { if(state!=='build')return;selected=-1;drag=null;state='attack';buildLeft=0;shots=4;shotTimer=.5;quietTimer=0;toast='Incoming! Your friend has four shots.';toastTime=2.2; }
  function rotateSelected() { if(selected>=0) { const p=pieces[selected];[p.w,p.h]=[p.h,p.w]; } }
  function cancelAim(){state='build';drag=null;}
  function spawnShot() {
    if(shots<=0)return;
    const target=blocks.filter(b=>b.hp>0).sort((a,b)=>Math.abs(a.x-960)-Math.abs(b.x-960))[0] || {x:960,y:550};
    const dx=target.x-sling.x, dy=target.y-sling.y, d=Math.hypot(dx,dy)||1;
    const speed=rand(500,610);
    birds.push({x:sling.x,y:sling.y,r:18,vx:dx/d*speed,vy:dy/d*speed-55,life:8,damage:3,enemy:true});
    shots--;shotTimer=1.65;
  }
  function particlesAt(x,y,color,n=12) { for(let i=0;i<n;i++) particles.push({x,y,vx:rand(-180,180),vy:rand(-220,80),r:rand(2,6),life:rand(.35,.8),color}); }
  function update(dt) {
    if(toastTime>0)toastTime-=dt;
    if(state==='attack') {
      shotTimer-=dt;
      if(shotTimer<=0&&shots>0)spawnShot();
      let moving=false;
      for(const b of blocks) {
        if(b.hp<=0)continue;
        // gravity / light settling makes stacks sway and collapse realistically
        b.vy=(b.vy||0)+360*dt; b.y+=(b.vy||0)*dt;
        let supported=b.y+b.h/2>=floorY;
        if(supported){b.y=floorY-b.h/2;b.vy=0;}
        for(const q of blocks) if(q!==b&&q.hp>0 && Math.abs(b.x-q.x)<(b.w+q.w)*.42 && b.y+b.h/2>=q.y-q.h/2 && b.y+b.h/2<q.y+q.h/2 && (b.vy||0)>=0) {b.y=q.y-(q.h+b.h)/2;b.vy=0;supported=true;}
        if(!supported)b.vx+=(Math.random()-.5)*8;
        b.x+=(b.vx||0)*dt; b.vx=(b.vx||0)*Math.pow(.985,dt*60);
        if(b.x<world.left+b.w/2){b.x=world.left+b.w/2;b.vx=Math.abs(b.vx)*.35;}
        if(b.x>world.right-b.w/2){b.x=world.right-b.w/2;b.vx=-Math.abs(b.vx)*.35;}
        if(Math.abs(b.vx)>8||Math.abs(b.vy)>12)moving=true;
      }
      for(const bird of birds) {
        if(!bird.enemy)continue;
        bird.vy+=380*dt;bird.x+=bird.vx*dt;bird.y+=bird.vy*dt;bird.life-=dt;
        for(const b of blocks) if(b.hp>0 && Math.abs(bird.x-b.x)<b.w/2+bird.r && Math.abs(bird.y-b.y)<b.h/2+bird.r) {
          const impact=Math.hypot(bird.vx,bird.vy);b.hp-=impact>350?bird.damage:1;b.vx+=bird.vx*.12;b.vy-=80;
          score+=Math.max(10,Math.round(impact*.04));particlesAt(bird.x,bird.y,b.kind==='glass'?'#bcffff':'#ffd09b',11);bird.life=0;break;
        }
        if(bird.y>floorY-10){bird.life=0;particlesAt(bird.x,floorY-8,'#efdb9c',6);}
      }
      birds=birds.filter(b=>b.life>0&&b.x<1320&&b.x>-30);
      blocks=blocks.filter(b=>{if(b.hp<=0){score+=35;particlesAt(b.x,b.y,b.kind==='stone'?'#c3cad4':b.kind==='glass'?'#aaf4ff':'#e6a86e',8);return false;}return true;});
      if(blocks.length===0){quietTimer=2;}
      if(shots===0&&birds.length===0) quietTimer+=dt; else quietTimer=0;
      if((shots===0&&birds.length===0&&quietTimer>1.3)||blocks.length===0&&quietTimer>0.5) {
        state='end';bestScore=Math.max(bestScore,score);toastTime=0;
      }
    }
    if(state==='build') {
      for(const b of blocks){b.vy=0;}
    }
    for(const p of particles){p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=420*dt;p.life-=dt;}
    particles=particles.filter(p=>p.life>0);
  }
