function overlay(){if(mode==='intro'){x.fillStyle='rgba(13,27,42,.23)';x.fillRect(0,0,W,H);box(355,172,570,333,28,'rgba(20,39,55,.91)','rgba(255,255,255,.3)',2);label('BIRDS',640,229,48,'#ffd065','center',1000);label('& BRICKS',640,277,48,'white','center',1000);label('BUILD A TOWER. YOUR FRIEND TRIES TO BREAK IT.',640,332,14,'#a8cbd1','center',900);bird(510,400,23);label('VS',640,405,15,'#f4d480','center');pig(770,400);label('Stack smart. See how many hits your nest can take.',640,457,13,'#e1ebdf','center',700);label('A tiny physics playground for friendly rivalries.',640,481,11,'#99b6bb','center',600)}if(mode==='end'){x.fillStyle='rgba(14,26,42,.28)';x.fillRect(0,0,W,H);box(390,205,500,272,25,'rgba(21,39,54,.94)','rgba(255,255,255,.26)',2);let win=blocks.length>0&&score>=250;label(win?'NEST DEFENDED!':'TOWER DOWN!',640,267,30,win?'#f7d16b':'#ff9679','center',1000);label(win?'Your friend ran out of ammo. Nice building!':'Your friend got through. Build it sturdier!',640,314,14,'#ecf1e8','center',700);label('FINAL SCORE   '+String(score).padStart(5,'0'),640,365,16,'white','center',900);label('Your best: '+String(best).padStart(5,'0'),640,396,12,'#b4c9ce','center',700)}if(noteTime>0&&mode!=='intro'&&mode!=='end'){box(400,105,480,34,11,'rgba(17,35,50,.65)');label(notice,640,122,12,'white','center',800)}}
function draw(){x.clearRect(0,0,W,H);background();box(888,547,145,54,10,'#d7b27c','#f6d69d',2);label('THE NEST',960,578,10,'#795a3a','center',900);pig(960,F-22);blocks.forEach(drawBlock);birds.forEach(b=>bird(b.x,b.y,b.r||18));bits.forEach(p=>{x.globalAlpha=clamp(p.life,0,1);x.fillStyle=p.color;x.beginPath();x.arc(p.x,p.y,p.r,0,7);x.fill();x.globalAlpha=1});slingDraw();hud();tray();overlay();if(mode==='build'&&pick>=0&&ghost){let p=kit[pick];x.globalAlpha=.65;drawBlock({x:ghost.x,y:ghost.y,w:p[2],h:p[3],kind:p[1],color:p[5],hp:p[6],max:p[6]});x.globalAlpha=1}}

function place(a,b){if(pick<0||kit[pick][4]<=0)return;let p=kit[pick],q={x:a,y:clamp(b,144,F-p[3]/2-2),w:p[2],h:p[3],kind:p[1],color:p[5],hp:p[6],max:p[6],vx:0,vy:0};for(let n=0;n<5;n++)for(const o of blocks)if(Math.abs(q.x-o.x)<(q.w+o.w)/2-5&&Math.abs(q.y-o.y)<(q.h+o.h)/2){let top=o.y-(o.h+q.h)/2-1,bot=o.y+(o.h+q.h)/2+1;q.y=Math.abs(q.y-top)<Math.abs(q.y-bot)?top:bot}q.x=clamp(q.x,180+q.w/2,1082-q.w/2);if(blocks.some(o=>Math.abs(q.x-o.x)<(q.w+o.w)/2-7&&Math.abs(q.y-o.y)<(q.h+o.h)/2-7)){notice='That spot is already occupied.';noteTime=1.5;return}blocks.push(q);p[4]--;pick=-1;ghost=null}
function attack(){mode='attack';pick=-1;ghost=null;shots=4;clock=.5;quiet=0;notice='Incoming! Your friend has four shots.';noteTime=2.2}
function rotate(){if(pick>=0){let p=kit[pick];[p[2],p[3]]=[p[3],p[2]]}}
function spawn(){let t=blocks.slice().sort((a,b)=>Math.abs(a.x-960)-Math.abs(b.x-960))[0]||{x:960,y:550},dx=t.x-300,dy=t.y-536,d=Math.hypot(dx,dy)||1,s=rand(500,610);birds.push({x:300,y:536,r:18,vx:dx/d*s,vy:dy/d*s-55,life:8,enemy:true,damage:3});shots--;clock=1.65}
function burst(a,b,color,n=12){for(let i=0;i<n;i++)bits.push({x:a,y:b,vx:rand(-180,180),vy:rand(-220,80),r:rand(2,6),life:rand(.35,.8),color})}
function update(dt){if(noteTime>0)noteTime-=dt;if(mode==='attack'){clock-=dt;if(clock<=0&&shots>0)spawn();for(let b of blocks){b.vy+=360*dt;b.y+=b.vy*dt;let supported=b.y+b.h/2>=F;if(supported){b.y=F-b.h/2;b.vy=0}for(let q of blocks)if(q!==b&&Math.abs(b.x-q.x)<(b.w+q.w)*.42&&b.y+b.h/2>=q.y-q.h/2&&b.y+b.h/2<q.y+q.h/2&&b.vy>=0){b.y=q.y-(q.h+b.h)/2;b.vy=0;supported=true}if(!supported)b.vx+=(Math.random()-.5)*8;b.x+=b.vx*dt;b.vx*=Math.pow(.985,dt*60)}for(let z of birds)if(z.enemy){z.vy+=380*dt;z.x+=z.vx*dt;z.y+=z.vy*dt;z.life-=dt;for(let b of blocks)if(b.hp>0&&Math.abs(z.x-b.x)<b.w/2+z.r&&Math.abs(z.y-b.y)<b.h/2+z.r){let impact=Math.hypot(z.vx,z.vy);b.hp-=impact>350?z.damage:1;b.vx+=z.vx*.12;b.vy-=80;score+=Math.max(10,Math.round(impact*.04));burst(z.x,z.y,b.kind==='glass'?'#bcffff':'#ffd09b',10);z.life=0;break}if(z.y>F-10)z.life=0}birds=birds.filter(z=>z.life>0&&z.x<1320&&z.x>-30);blocks=blocks.filter(b=>{if(b.hp<=0){score+=35;burst(b.x,b.y,b.kind==='stone'?'#c3cad4':b.kind==='glass'?'#aaf4ff':'#e6a86e',8);return false}return true});if(shots===0&&birds.length===0)quiet+=dt;else quiet=0;if((shots===0&&birds.length===0&&quiet>2)||(blocks.length===0&&quiet>1)){mode='end';best=Math.max(best,score);noteTime=0}}for(let p of bits){p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=420*dt;p.life-=dt}bits=bits.filter(p=>p.life>0)}
function point(e){let r=c.getBoundingClientRect();return{x:(e.clientX-r.left)*W/r.width,y:(e.clientY-r.top)*H/r.height}}
c.addEventListener('pointerdown',e=>{e.preventDefault();let p=point(e);c.setPointerCapture(e.pointerId);for(let z of buttons.slice().reverse())if(p.x>=z.a&&p.x<=z.a+z.w&&p.y>=z.b&&p.y<=z.b+z.h){z.fn();return}if(mode==='build'){for(let i=0;i<kit.length;i++){let a=34+i*147;if(p.x>=a&&p.x<a+137&&p.y>=655&&p.y<=697){pick=kit[i][4]>0?i:-1;ghost=null;return}}if(pick>=0)ghost=p}else if(mode==='aim'&&ghost)launch(p)});
c.addEventListener('pointermove',e=>{if(ghost)ghost=point(e)});c.addEventListener('pointerup',e=>{let p=point(e);if(mode==='build'&&ghost){if(p.y<F-15&&p.y>144&&p.x>178&&p.x<1084)place(p.x,p.y);else ghost=null}else if(mode==='aim'&&ghost)launch(p)});
function launch(p){let dx=300-p.x,dy=536-p.y;if(Math.hypot(dx,dy)<20){ghost=null;mode='build';return}birds.push({x:300,y:536,vx:dx*4.4,vy:dy*4.4,r:19,life:6,enemy:false,damage:4});mode='build';ghost=null;pick=-1;notice='Nice shot! Keep building your defenses.';noteTime=2}
window.addEventListener('keydown',e=>{if(e.key.toLowerCase()==='r')rotate();if(e.key==='Escape'){pick=-1;ghost=null}if((e.key===' '||e.key==='Enter')&&mode==='intro')start()});let last=performance.now();function frame(now){let dt=Math.min(.033,(now-last)/1000);last=now;update(dt);draw();requestAnimationFrame(frame)}requestAnimationFrame(frame)
})();

