(()=>{
const c=document.querySelector('#game'),x=c.getContext('2d'),W=1280,H=720,F=610;
const kit=[['PLANK','wood',138,24,5,'#c98249',2],['STONE','stone',72,52,4,'#858da3',4],['GLASS','glass',98,16,3,'#82d8e6',1],['SHORT','wood',72,22,4,'#d59658',2]];
let mode='intro',pick=-1,ghost=null,blocks=[],birds=[],bits=[],score=0,shots=4,clock=0,quiet=0,best=0,notice='',noteTime=0,buttons=[];
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v)),rand=(a,b)=>a+Math.random()*(b-a);
function label(s,a,b,size=14,color='#fff',align='left',weight=700){x.font=`${weight} ${size}px system-ui`;x.textAlign=align;x.textBaseline='middle';x.fillStyle=color;x.fillText(s,a,b)}
function box(a,b,w,h,r,fill,stroke='rgba(255,255,255,.2)',lw=1){x.beginPath();x.roundRect(a,b,w,h,r);x.fillStyle=fill;x.fill();if(stroke){x.strokeStyle=stroke;x.lineWidth=lw;x.stroke()}}
function btn(s,a,b,w,h,color,fn,sub=''){box(a,b+4,w,h,13,'rgba(0,0,0,.2)',null);box(a,b,w,h,13,color);label(s,a+w/2,b+h/2-(sub?6:0),15,'white','center',900);if(sub)label(sub,a+w/2,b+h/2+12,9,'#ddd','center');buttons.push({a,b,w,h,fn})}
function start(){kit.forEach((p,i)=>p[4]=[5,4,3,4][i]);blocks=[];birds=[];bits=[];score=0;shots=4;pick=-1;ghost=null;mode='build';notice='Pick a block, then place it around the pig!';noteTime=3}
function background(){let g=x.createLinearGradient(0,0,0,720);g.addColorStop(0,'#78c9e8');g.addColorStop(.64,'#c7e9e9');g.addColorStop(1,'#e5ddb0');x.fillStyle=g;x.fillRect(0,0,W,H);x.fillStyle='rgba(255,244,179,.75)';x.beginPath();x.arc(1070,140,53,0,7);x.fill();for(const [a,b,s] of [[210,145,1],[560,105,.72],[890,230,.65]]){x.fillStyle='rgba(255,255,255,.52)';x.beginPath();x.ellipse(a,b,45*s,16*s,0,0,7);x.ellipse(a+25*s,b-9*s,28*s,19*s,0,0,7);x.ellipse(a-22*s,b-6*s,24*s,15*s,0,0,7);x.fill()}x.fillStyle='#9bceaa';x.beginPath();x.moveTo(0,434);x.quadraticCurveTo(226,320,465,430);x.quadraticCurveTo(730,540,1000,398);x.quadraticCurveTo(1160,337,1280,405);x.lineTo(1280,640);x.lineTo(0,640);x.fill();x.fillStyle='#75b88b';x.beginPath();x.moveTo(0,508);x.quadraticCurveTo(250,418,494,505);x.quadraticCurveTo(829,596,1050,470);x.quadraticCurveTo(1170,421,1280,480);x.lineTo(1280,640);x.lineTo(0,640);x.fill();for(let i=0;i<17;i++){let a=35+i*79,b=520+Math.sin(a*.03)*28;x.fillStyle='#4d9877';x.fillRect(a,b,7,45);x.beginPath();x.arc(a+4,b,18,0,7);x.fill()}x.fillStyle='#e8c879';x.fillRect(0,F,W,H-F);x.fillStyle='#fff0b0';x.fillRect(0,F,W,8);box(671,F-12,367,20,8,'#b57c53','#f4d293',2)}
function bird(a,b,r=19){x.fillStyle='#ed5547';x.beginPath();x.arc(a,b,r,0,7);x.fill();x.fillStyle='#fff4dc';x.beginPath();x.ellipse(a+6,b+5,9,7,-.3,0,7);x.fill();x.fillStyle='white';x.beginPath();x.arc(a+6,b-5,6,0,7);x.arc(a+14,b-4,5,0,7);x.fill();x.fillStyle='#263448';x.beginPath();x.arc(a+8,b-5,2,0,7);x.arc(a+15,b-4,2,0,7);x.fill();x.fillStyle='#f6b83f';x.beginPath();x.moveTo(a+10,b+1);x.lineTo(a+26,b+5);x.lineTo(a+10,b+9);x.fill()}
function pig(a,b){x.fillStyle='#84c958';x.beginPath();x.ellipse(a,b,22,19,0,0,7);x.fill();x.fillStyle='#a7df75';x.beginPath();x.ellipse(a-10,b-16,7,10,-.5,0,7);x.ellipse(a+10,b-16,7,10,.5,0,7);x.fill();x.fillStyle='#fff';x.beginPath();x.arc(a-7,b-3,5,0,7);x.arc(a+7,b-3,5,0,7);x.fill();x.fillStyle='#263448';x.beginPath();x.arc(a-6,b-2,2,0,7);x.arc(a+8,b-2,2,0,7);x.fill();x.fillStyle='#64a743';x.beginPath();x.ellipse(a,b+6,8,5,0,0,7);x.fill()}
function drawBlock(b){x.save();x.translate(b.x,b.y);x.rotate(b.angle||0);let fill=b.kind==='glass'?'rgba(112,224,237,.72)':b.kind==='stone'?'#858da3':b.color,stroke=b.kind==='glass'?'#e7ffff':b.kind==='stone'?'#b9c1d0':'#f0bd7d';box(-b.w/2,-b.h/2,b.w,b.h,Math.min(7,b.h/4),fill,stroke,3);if(b.kind==='wood'){x.strokeStyle='rgba(97,48,26,.36)';x.beginPath();x.moveTo(-b.w*.35,0);x.lineTo(b.w*.35,0);x.stroke()}if(b.kind==='glass'){x.fillStyle='rgba(255,255,255,.7)';x.fillRect(-b.w*.35,-b.h*.25,b.w*.22,3)}if(b.hp<b.max){x.strokeStyle='#403833';x.beginPath();x.moveTo(-b.w*.13,-b.h*.4);x.lineTo(-b.w*.02,0);x.lineTo(-b.w*.2,b.h*.35);x.stroke()}x.restore()}

function slingDraw(){x.lineCap='round';x.lineWidth=17;x.strokeStyle='#77452f';x.beginPath();x.moveTo(300,F-4);x.lineTo(302,523);x.lineTo(282,478);x.moveTo(302,523);x.lineTo(326,479);x.stroke();x.lineWidth=7;x.strokeStyle='#a86b40';x.beginPath();x.moveTo(300,F-4);x.lineTo(302,523);x.stroke();if(mode==='aim'&&ghost){x.lineWidth=4;x.strokeStyle='#704334';x.beginPath();x.moveTo(282,478);x.lineTo(ghost.x,ghost.y);x.lineTo(326,479);x.stroke();x.setLineDash([6,7]);x.strokeStyle='rgba(255,255,255,.75)';x.lineWidth=2;x.beginPath();let vx=(300-ghost.x)*.14,vy=(536-ghost.y)*.14;for(let i=0;i<24;i++){let t=i*.13,a=300+vx*t,b=536+vy*t+210*t*t;if(i)x.lineTo(a,b);else x.moveTo(a,b)}x.stroke();x.setLineDash([])}bird(mode==='aim'&&ghost?ghost.x:300,mode==='aim'&&ghost?ghost.y:536,20)}
function hud(){box(24,22,380,70,19,'rgba(16,30,50,.84)');label('BIRDS',45,47,19,'#ffcb62');label('& BRICKS',111,47,19);label('BUILD. BRACE. BONK.',46,72,11,'#bad0d4');box(1015,24,240,64,17,'rgba(16,30,50,.78)');label('SCORE',1038,45,11,'#b4c9d1');label(String(score).padStart(5,'0'),1038,68,22);label('♥  '+(mode==='build'?4:shots),1178,48,14,'#ffd56d','center',900);if(mode==='build'||mode==='aim'){box(414,24,482,58,16,'rgba(255,255,255,.76)');label(mode==='build'?'YOUR TURN · FORTIFY THE NEST':'READY, AIM…',655,44,13,'#264b5b','center',900);label(mode==='build'?'Stack blocks around your pig, then let your friend attack.':'Drag back and release to fling your bird!',655,64,11,'#55727a','center',700)}else if(mode==='attack'){box(435,24,410,58,16,'rgba(30,40,58,.75)');label('INCOMING! FRIEND IS ATTACKING',640,43,13,'white','center',900);label('Hold your tower together!',640,64,11,'#cfdae0','center',700)}}
function tray(){buttons=[];if(mode==='build'||mode==='aim'){box(18,626,1244,80,17,'rgba(19,35,49,.92)');label('BUILD KIT',38,646,10,'#9fbac1','left',900);kit.forEach((p,i)=>{let a=34+i*147,active=pick===i;box(a,655,137,42,10,active?'#e7b45a':'#304c5d',active?'#fff0b0':'rgba(255,255,255,.14)',active?2:1);x.fillStyle=p[5];x.fillRect(a+10,668,26,15);label(p[0],a+43,668,9,active?'#382f20':'#fff','left',900);label('× '+p[4],a+43,685,10,active?'#57462b':'#b9d1d2')});btn('ROTATE  R',635,652,111,40,'#476478',rotate,'Turn block');if(mode==='build')btn('LET HIM TRY  →',765,646,211,50,'#df7350',attack,'Start the attack');else btn('CANCEL',765,646,211,50,'#566778',()=>{mode='build';ghost=null});btn('RESET',1101,652,117,40,'#405367',start)}else if(mode==='end'){box(18,626,1244,80,17,'rgba(19,35,49,.92)');label('THE ROUND IS OVER',40,655,14,'#f5d875');label('Want a rematch? Build a better nest.',40,680,11,'#b9d1d2');btn('PLAY AGAIN',1034,644,190,52,'#df7350',start)}else{box(18,626,1244,80,17,'rgba(19,35,49,.92)');label('HOW TO PLAY',40,650,11,'#ffd36c');label('Pick blocks · click to place · drag to aim · let your friend attack!',40,678,15);btn('PLAY',1050,644,174,52,'#df7350',start)}}
function overlay(){if(mode==='intro'){x.fillStyle='rgba(13,27,42,.23)';x.fillRect(0,0,W,H);box(355,172,570,333,28,'rgba(20,39,55,.91)','rgba(255,255,255,.3)',2);label('BIRDS',640,229,48,'#ffd065','center',1000);label('& BRICKS',640,277,48,'white','center',1000);label('BUILD A TOWER. YOUR FRIEND TRIES TO BREAK IT.',640,332,14,'#a8cbd1','center',900);bird(510,400,23);label('VS',640,405,15,'#f4d480','center');pig(770,400);label('Stack smart. See how many hits your nest can take.',640,457,13,'#e1ebdf','center',700);label('A tiny physics playground for friendly rivalries.',640,481,11,'#99b6bb','center',600)}if(mode==='end'){x.fillStyle='rgba(14,26,42,.28)';x.fillRect(0,0,W,H);box(390,205,500,272,25,'rgba(21,39,54,.94)','rgba(255,255,255,.26)',2);let win=blocks.length>0&&score>=250;label(win?'NEST DEFENDED!':'TOWER DOWN!',640,267,30,win?'#f7d16b':'#ff9679','center',1000);label(win?'Your friend ran out of ammo. Nice building!':'Your friend got through. Build it sturdier!',640,314,14,'#ecf1e8','center',700);label('FINAL SCORE   '+String(score).padStart(5,'0'),640,365,16,'white','center',900);label('Your best: '+String(best).padStart(5,'0'),640,396,12,'#b4c9ce','center',700)}if(noteTime>0&&mode!=='intro'&&mode!=='end'){box(400,105,480,34,11,'rgba(17,35,50,.65)');label(notice,640,122,12,'white','center',800)}}
function draw(){x.clearRect(0,0,W,H);background();box(888,547,145,54,10,'#d7b27c','#f6d69d',2);label('THE NEST',960,578,10,'#795a3a','center',900);pig(960,F-22);blocks.forEach(drawBlock);birds.forEach(b=>bird(b.x,b.y,b.r||18));bits.forEach(p=>{x.globalAlpha=clamp(p.life,0,1);x.fillStyle=p.color;x.beginPath();x.arc(p.x,p.y,p.r,0,7);x.fill();x.globalAlpha=1});slingDraw();hud();tray();overlay();if(mode==='build'&&pick>=0&&ghost){let p=kit[pick];x.globalAlpha=.65;drawBlock({x:ghost.x,y:ghost.y,w:p[2],h:p[3],kind:p[1],color:p[5],hp:p[6],max:p[6]});x.globalAlpha=1}}

function place(a,b){if(pick<0||kit[pick][4]<=0)return;let p=kit[pick],q={x:a,y:clamp(b,144,F-p[3]/2-2),w:p[2],h:p[3],kind:p[1],color:p[5],hp:p[6],max:p[6],vx:0,vy:0};for(let n=0;n<5;n++)for(const o of blocks)if(Math.abs(q.x-o.x)<(q.w+o.w)/2-5&&Math.abs(q.y-o.y)<(q.h+o.h)/2){let top=o.y-(o.h+q.h)/2-1,bot=o.y+(o.h+q.h)/2+1;q.y=Math.abs(q.y-top)<Math.abs(q.y-bot)?top:bot}q.x=clamp(q.x,180+q.w/2,1082-q.w/2);if(blocks.some(o=>Math.abs(q.x-o.x)<(q.w+o.w)/2-7&&Math.abs(q.y-o.y)<(q.h+o.h)/2-7)){notice='That spot is already occupied.';noteTime=1.5;return}blocks.push(q);p[4]--;pick=-1;ghost=null}
function attack(){mode='attack';pick=-1;ghost=null;shots=4;clock=.5;quiet=0;notice='Incoming! Your friend has four shots.';noteTime=2.2}
function rotate(){if(pick>=0){let p=kit[pick];[p[2],p[3]]=[p[3],p[2]]}}
function spawn(){let t=blocks.slice().sort((a,b)=>Math.abs(a.x-960)-Math.abs(b.x-960))[0]||{x:960,y:550},dx=t.x-300,dy=t.y-536,d=Math.hypot(dx,dy)||1,s=rand(500,610);birds.push({x:300,y:536,r:18,vx:dx/d*s,vy:dy/d*s-55,life:8,enemy:true,damage:3});shots--;clock=1.65}
function burst(a,b,color,n=12){for(let i=0;i<n;i++)bits.push({x:a,y:b,vx:rand(-180,180),vy:rand(-220,80),r:rand(2,6),life:rand(.35,.8),color})}
function update(dt){if(noteTime>0)noteTime-=dt;if(mode==='attack'){clock-=dt;if(clock<=0&&shots>0)spawn();for(let b of blocks){b.vy+=360*dt;b.y+=b.vy*dt;let supported=b.y+b.h/2>=F;if(supported){b.y=F-b.h/2;b.vy=0}for(let q of blocks)if(q!==b&&Math.abs(b.x-q.x)<(b.w+q.w)*.42&&b.y+b.h/2>=q.y-q.h/2&&b.y+b.h/2<q.y+q.h/2&&b.vy>=0){b.y=q.y-(q.h+b.h)/2;b.vy=0;supported=true}if(!supported)b.vx+=(Math.random()-.5)*8;b.x+=b.vx*dt;b.vx*=Math.pow(.985,dt*60)}for(let z of birds)if(z.enemy){z.vy+=380*dt;z.x+=z.vx*dt;z.y+=z.vy*dt;z.life-=dt;for(let b of blocks)if(b.hp>0&&Math.abs(z.x-b.x)<b.w/2+z.r&&Math.abs(z.y-b.y)<b.h/2+z.r){let impact=Math.hypot(z.vx,z.vy);b.hp-=impact>350?z.damage:1;b.vx+=z.vx*.12;b.vy-=80;score+=Math.max(10,Math.round(impact*.04));burst(z.x,z.y,b.kind==='glass'?'#bcffff':'#ffd09b',10);z.life=0;break}if(z.y>F-10)z.life=0}birds=birds.filter(z=>z.life>0&&z.x<1320&&z.x>-30);blocks=blocks.filter(b=>{if(b.hp<=0){score+=35;burst(b.x,b.y,b.kind==='stone'?'#c3cad4':b.kind==='glass'?'#aaf4ff':'#e6a86e',8);return false}return true});if(shots===0&&birds.length===0)quiet+=dt;else quiet=0;if((shots===0&&birds.length===0&&quiet>2)||(blocks.length===0&&quiet>1)){mode='end';best=Math.max(best,score);noteTime=0}}for(let p of bits){p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=420*dt;p.life-=dt}bits=bits.filter(p=>p.life>0)}
function point(e){let r=c.getBoundingClientRect();return{x:(e.clientX-r.left)*W/r.width,y:(e.clientY-r.top)*H/r.height}}
c.addEventListener('pointerdown',e=>{e.preventDefault();let p=point(e);c.setPointerCapture(e.pointerId);for(let z of buttons.slice().reverse())if(p.x>=z.a&&p.x<=z.a+z.w&&p.y>=z.b&&p.y<=z.b+z.h){z.fn();return}if(mode==='build'){for(let i=0;i<kit.length;i++){let a=34+i*147;if(p.x>=a&&p.x<a+137&&p.y>=655&&p.y<=697){pick=kit[i][4]>0?i:-1;ghost=null;return}}if(pick>=0)ghost=p}else if(mode==='aim'&&ghost)launch(p)});
c.addEventListener('pointermove',e=>{if(ghost)ghost=point(e)});c.addEventListener('pointerup',e=>{let p=point(e);if(mode==='build'&&ghost){if(p.y<F-15&&p.y>144&&p.x>178&&p.x<1084)place(p.x,p.y);else ghost=null}else if(mode==='aim'&&ghost)launch(p)});
function launch(p){let dx=300-p.x,dy=536-p.y;if(Math.hypot(dx,dy)<20){ghost=null;mode='build';return}birds.push({x:300,y:536,vx:dx*4.4,vy:dy*4.4,r:19,life:6,enemy:false,damage:4});mode='build';ghost=null;pick=-1;notice='Nice shot! Keep building your defenses.';noteTime=2}
window.addEventListener('keydown',e=>{if(e.key.toLowerCase()==='r')rotate();if(e.key==='Escape'){pick=-1;ghost=null}if((e.key===' '||e.key==='Enter')&&mode==='intro')start()});let last=performance.now();function frame(now){let dt=Math.min(.033,(now-last)/1000);last=now;update(dt);draw();requestAnimationFrame(frame)}requestAnimationFrame(frame)
})();

